      await _waiting.printHeadlessDetachSummary();
    } else {
      await _awaitHeadlessBackgroundJobs();
      // Visible waiting (issue #450): stay for the waiters when opted in,
      // otherwise print the honest detach summary before exiting.
      await _waiting.waitForJobsOrSummarize(waitForJobs: waitForJobs);
    }
  } catch (error) {
    io.writeln(
      _keyStatusView.errorLine('$error', _agent.state.model.baseUrl),
    );
    return 1;
  } finally {
    _headlessMode = false;
    _autoFoldCount = 0;
    turnSub();
    await releasePowerAssertions();
    await _cubeCacheSaveQuietly();
    await interruptSub.cancel();
    await taskSub.cancel();
    hepSub?.call();
    streamJsonSub?.call();
    // gh-1241: close the usage segment — fold the chain, write
    // usage.json, log the `fa-tokens:` line (a kill mid-segment loses
    // nothing: the fold rebuilds from the chain on the next close).
    // gh-1292: mirror that line onto the diagnostics channel (stderr
    // on this headless leg) — the diag file dies with the runner, and
    // the token reporter greps the captured run log. Stdout stays the
    // pipeable prose stream (issue #774 AC3).
    await _flushUsageLedger(mirrorTokensLineToRunLog: true);
    // gh-1590: land a coalesced job-board snapshot and disarm the
    // throttle's trailing leg — a headless exit must not leave a
    // pending Timer holding the isolate, nor a final board state
    // missing from the ledger. The obligations ledger and the
    // subagent registry flush the same way.
    await _flushJobBoardPersist();
    await _flushObligationsLedger();
    await _subagentManager.flushPersist();
  }
  // gh-1603: the exit-code policy lives in the part-file extension — an
  // unfinished session prints the explicit marker and exits 1; error/
  // aborted terminals keep their own codes.
  return _headlessExitCode(
    endedOnEmptyCompletion: endedOnEmptyCompletion,
    terminalStopReason: terminalStopReason,
  );
}

