/// Usage as a fake provider that omits usage deserializes to: all zeros.
Map<String, dynamic> get omittedUsage => {
  'input': 0,
  'output': 0,
  'cacheRead': 0,
  'cacheWrite': 0,
  'totalTokens': 0,
  'cost': const {'total': 0.0},
};

