  String model = 'model-a',
  Map<String, dynamic>? usage,
  List<String> texts = const ['hello world'],
}) => jsonEncode({
  ..._recordBase(n),
  'type': 'message',
  'message': {
    'role': 'assistant',
    'content': [
      for (final text in texts) {'type': 'text', 'text': text},
    ],
    'api': 'test',
    'provider': 'test',
    'model': model,
    'usage': usage ?? reportedUsage(),
    'stopReason': 'stop',
    'timestamp': 1700000000000,
  },
});

/// One user `message` record (must be ignored by the fold).
String userLine(int n, {String text = 'do the thing'}) => jsonEncode({
  ..._recordBase(n),
  'type': 'message',
  'message': {'role': 'user', 'content': text, 'timestamp': 1700000000000},
});

/// A non-message, non-custom record (checkpoint/label/...): the scanner
/// ignores it for token sums but its timestamp still stamps the current
/// segment's `closedAt` (chain "last contributing record").
String otherRecordLine(int n, {String type = 'checkpoint'}) =>
    jsonEncode({..._recordBase(n), 'type': type});

