        if len(safe) <= _MAX_VERIFIER_ENV_SESSION_ID_LEN:
            return safe

        digest = hashlib.sha1(safe.encode()).hexdigest()[:8]
        suffix = f"__{digest}"
        prefix = safe[: _MAX_VERIFIER_ENV_SESSION_ID_LEN - len(suffix)].rstrip("-._")
        return f"{prefix}{suffix}"

