import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'usage_chain_fixtures.dart';

UsageLedger foldChain(List<String> lines, {String sessionId = 'sess-1'}) =>
