{"command":"python3 - <<'EOF'
import json
with open('/tmp/shard0-fail.json') as f:
    lines = [l for l in f if l.strip()]
docs = []
dec = json.JSONDecoder()
idx = 0
data = ''.join(lines)
while idx < len(data):
    data2 = data[idx:].lstrip()
    if not data2:
        break
    obj, off = dec.raw_decode(data2)
    docs.append(obj)
    idx = len(data) - len(data2) + off
byid = {}
for d in docs:
    if isinstance(d, dict) and 'testID' in d:
        byid.update({d['testID']: d} if 'testID' in d and 'name' not in d else {})
# simpler: collect start events for names
names = {}
for d in docs:
    t = d.get('type') if isinstance(d, dict) else None
    if t == 'testStart':
        names[d['test']['id']] = d['test']['name']
    elif t == 'testDone' and d.get('result') not in ('success', 'skip') and not d.get('hidden'):
        print('FAILED:', names.get(d['testID'], d['testID']), '->', d.get('result'))
    elif t == 'error':
        print('ERROR for', names.get(d.get('testID')), ':')
        print((d.get('error') or '')[:2000])
EOF"}

